async function seedDatabase() {
  try {
    log('info', 'Checking if seeding is needed...');

    // Check if demo user exists
    let demoUser;
    try {
      const users = await adminPb.collection('users').getFullList({
        filter: 'email = "demo@ethara.ai"',
      });
      if (users.length > 0) {
        demoUser = users[0];
        log('info', 'Demo user already exists, skipping seed');
        return;
      }
    } catch (err) {
      // Collection might not exist yet or other error
      log('info', 'Could not check for existing user, will attempt to seed');
    }

    // Create demo user
    log('info', 'Creating demo user...');
    demoUser = await adminPb.collection('users').create({
      email: 'demo@ethara.ai',
      password: 'deku-demo-pw-2026',
      passwordConfirm: 'deku-demo-pw-2026',
      emailVisibility: true,
    });
    log('info', 'Demo user created', { userId: demoUser.id });

    const today = getToday();

    // Helper to get date N days ago
    function daysAgo(n) {
      const d = new Date(today);
      d.setDate(d.getDate() - n);
      return d.toISOString().split('T')[0];
    }

    // Create habits
    const meditateHabit = await adminPb.collection('habits').create({
      user_id: demoUser.id,
      name: 'Meditate',
      color: 'indigo',
      description: '',
      deleted: false,
    });
    log('info', 'Created Meditate habit', { habitId: meditateHabit.id });

    const readHabit = await adminPb.collection('habits').create({
      user_id: demoUser.id,
      name: 'Read 20 minutes',
      color: 'teal',
      description: '',
      deleted: false,
    });
    log('info', 'Created Read 20 minutes habit', { habitId: readHabit.id });

    const sodaHabit = await adminPb.collection('habits').create({
      user_id: demoUser.id,
      name: 'No soda',
      color: 'amber',
      description: '',
      deleted: false,
    });
    log('info', 'Created No soda habit', { habitId: sodaHabit.id });

    // Create completions for Meditate: current_streak = 5 (today + 4 previous days)
    for (let i = 0; i < 5; i++) {
      await adminPb.collection('completions').create({
        habit_id: meditateHabit.id,
        user_id: demoUser.id,
        date: daysAgo(i),
      });
    }
    log('info', 'Created Meditate completions (5 day streak)');

    // Create completions for Read 20 minutes: current_streak = 0, longest_streak >= 3
    // 3 consecutive days earlier this month, nothing today
    for (let i = 10; i < 13; i++) {
      await adminPb.collection('completions').create({
        habit_id: readHabit.id,
        user_id: demoUser.id,
        date: daysAgo(i),
      });
    }
    log('info', 'Created Read 20 minutes completions (3 day streak earlier)');

    // Create completions for No soda: current_streak = 1 (today only, gap yesterday)
