    log('info', 'Created Read 20 minutes habit', { habitId: readHabit.id });

    const sodaHabit = await userPb.collection('habits').create({
      user_id: demoUser.id,
      name: 'No soda',
      color: 'amber',
      description: '',
      deleted: false,
    });
    log('info', 'Created No soda habit', { habitId: sodaHabit.id });

